import axios from "axios";


export function getDogs() {
  return async (dispatch) => {
    try {
        var dog = await axios('http://localhost:3001/dogs');
        return dispatch({
            type: GET_DOGS,
            payload: dog.data
           
        })
    } catch (error) {
        console.log(error);
    }

}
}


export function getTemperaments() {
  return async function (dispatch) {
    try {
      var res = await axios.get("http://localhost:3001/temperaments");
      return dispatch({
        type: GET_TEMPERAMENTS,
        payload: res.data
      });
    } catch (error) {
      alert(error);
    }
  };
}

export const getByName = (name)=> async dispatch => {
  try{
    await axios.get('http://localhost:3001/dogs?name='+ name)
    .then((response) => {
        dispatch({
            type: GET_BY_NAME,
            payload: response.data
        })
    })
 } catch (error) { 
    return alert("Raza no encontrada")
 }
}

export const getDetail = (id) => async dispatch =>{
  try {
    dispatch({
        type: LOADING
     })
  await axios.get(`http://localhost:3001/dogs/${id}`)
  .then((response) => {
      dispatch({
          type: GET_DETAIL,
          payload: response.data
      })
  })    
  } catch (error) { console.log(error)}
}

export const getByTemperaments = () => async dispatch =>{
  try{
      await axios.get('http://localhost:3001/temperaments')
      .then((response) => {
          dispatch({
              type: GET_BY_TEMPERAMENTS,
              payload: response.data
          })            
      })
  } catch (error){
      return (error)
  }
}

export function filterBy(payload) {
  return function (dispatch) {
    dispatch({ type: FILTER_BY, payload });
  };
}

export function filterTemperament(payload){
  return{
      type: FILTER_TEMPERAMENT,
      payload
  }
}
export function orderBy(order) {
  return function (dispatch) {
    dispatch({ type: ORDER_BY, payload: order });
    };
}

export function clean(){
  return function(dispatch){
    dispatch({type:CLEAN})
  }
}

export const paginate = (page) => (dispatch) => {
  dispatch({type: PAGINATE, payload: page})
}
